"""Round 4: cold starts with snapshots, Kokoro on an L4 the way production runs it and Phonon on
1 CPU core with a memory snapshot.

Deployed (not `modal run`) so snapshots are kept between containers:
`uv run modal deploy modal_snap.py`, then `uv run python snap_client.py`, then `modal app stop`.
"""

import time

import modal

from modal_app import kokoro_image, phonon_image

app = modal.App("nagara-spike-tts-snap")


class Bench:
    engine: str

    @modal.enter(snap=True)
    def load(self):
        import bench

        self.loaded = bench.load(self.engine)

    @modal.enter(snap=False)
    def ready(self):
        self.ready_at = time.time()

    @modal.method()
    def bench(self, paragraphs: list[str], called_at: float) -> tuple[dict, bytes]:
        import bench

        started_at = time.time()
        metrics, opus = bench.run(self.engine, paragraphs, loaded=self.loaded)
        metrics["call_to_method_s"] = round(started_at - called_at, 2)
        metrics["ready_to_method_s"] = round(started_at - self.ready_at, 2)

        return metrics, opus


@app.cls(
    image=kokoro_image,
    gpu="L4",
    scaledown_window=2,
    enable_memory_snapshot=True,
    experimental_options={"enable_gpu_snapshot": True},
    timeout=1800,
)
class KokoroL4(Bench):
    engine = "kokoro"


@app.cls(image=phonon_image, cpu=1.0, memory=1024, scaledown_window=2, enable_memory_snapshot=True, timeout=1800)
class PhononCPU(Bench):
    engine = "phonon"

