(async () => {
  const c = window.canvas
  editor.selectNone()
  const pairs = [
    ["Checked in the enqueue request schema: a mismatch answers 400 and no row is written.", "The enqueue request schema checks the match. On a mismatch the API answers 400 and writes no row."],
    ["Unchanged fields are left out.", "The diagram leaves out unchanged fields."],
    ["The string is stored on the row, passed unchanged to Modal and returned on every poll.", "The API stores the string on the row, the pipeline passes it unchanged to Modal, and every poll returns it."],
    ["Nothing outside tts/ names a model: Kokoro is fixed by the Modal app that MODAL_START_URL points at.", "Nothing outside tts/ names a model. The Modal app that MODAL_START_URL points at hard-codes Kokoro."],
    ["a mismatch is rejected", "the API rejects a mismatch"],
    ["Yes, independent at run time, verified:", "Yes, the two classes run independently, and the spike verified it:"],
    ["whether that also discards Kokoro's snapshot (and its next cold start pays ~29 s again) is not verified.", "nobody has verified whether that also discards Kokoro's snapshot. If it does, Kokoro's next cold start takes about 29 s again."],
    ["The docs are unified with the change when it is built.", "Whoever builds the change updates the docs to match it."],
    ["No spike. Both models in one Modal app.", "No redeploy spike runs. Both models run in one Modal app."],
    ["This is a change to the item JSON, so item-contract.md gets it (the project rule for any change to the item JSON).", "This changes the item JSON, and the project rule puts every change to the item JSON in item-contract.md."],
    ["What Kokoro does with a b-voice on an \"a\" pipeline (fail, or speak with American pronunciation) is not verified.", "Nobody has verified whether Kokoro fails on a b-voice in an \"a\" pipeline or speaks it with American pronunciation."],
    ["No model anywhere:", "No code names a model:"],
    ["voice is never validated: an unknown voice is stored and fails later, inside Modal.", "Nothing validates voice. The API stores an unknown voice, and synthesis fails later inside Modal."],
    ["a British Kokoro voice such as bf_emma is then rejected at enqueue with a 400", "the API then rejects a British Kokoro voice such as bf_emma at enqueue with a 400"],
    ["a ~29 s first cold start", "a first cold start of about 29 s"],
    ["The project asks that audio is listened to, not only measured.", "The project asks that someone listen to the audio, not only measure it."],
    ["VOICE_POOL and pickVoice give way to the catalog and its defaults", "the catalog in common/ and its defaults replace VOICE_POOL and pickVoice"],
    ["the af_heart default moves out", "StartRequest.voice loses its af_heart default, because the API now always sends a voice"],
  ]
  const applied = [], missing = []
  const shapes = editor.getCurrentPageShapes()
  for (const [a, b] of pairs) {
    let hit = false
    for (const s of shapes) {
      const name = s.id.replace('shape:', '')
      let t; try { t = c.plain(name) } catch { continue }
      if (!t || !t.includes(a)) continue
      const next = t.replace(a, b)
      if (name.startsWith('note') || name.endsWith('-note')) await c.note(name, { text: next.replace(/^Claude\s*/, '') }, 50)
      else if (s.type === 'text') await c.text(name, { text: next }, 50)
      else await c.card(name, { text: next }, 50)
      hit = true; applied.push(name)
    }
    if (!hit) missing.push(a.slice(0, 40))
  }
  for (const n of ['today', 'proposed', 'review']) await c.fit(n)
  return JSON.stringify({ applied, missing })
})()
EOF
